import{a as p}from"./chunk-DSEWHCCG.js";import{a as r}from"./chunk-2EDCWSCQ.js";import"./chunk-5II3MPMJ.js";import"./chunk-TRYNAU5S.js";import{a as f}from"./chunk-ASS7GFNI.js";import{a as c}from"./chunk-C7PGRU37.js";import{X as F}from"./chunk-K3IKQ6MG.js";import"./chunk-2MU6OKRB.js";import{Ra as t,ta as d,ub as g,xa as l}from"./chunk-RIQZW2OE.js";import{a as s,b as a,h as k}from"./chunk-TWZW5B45.js";var m=k(F());var y={category:f,title:"Config Files",mdFile:"./index.md",order:p("config-files")},o=y;var h=[];var b={},u=b;var w='<p class="ngde">The <code class="ngde">@angularity/config-files</code> package offers a declarative and flexible access to remote config files, such as static JSON/YAML/XML files or config REST APIs.</p><pre class="shiki shiki-themes github-light ayu-dark" style="background-color:#fff;--shiki-dark-bg:#0b0e14;color:#24292e;--shiki-dark:#bfbdb6" tabindex="0"><code class="language-sh"><span class="line"><span style="color:#6F42C1;--shiki-dark:#59C2FF" class="ngde">npm</span><span style="color:#032F62;--shiki-dark:#AAD94C" class="ngde"> i</span><span style="color:#032F62;--shiki-dark:#AAD94C" class="ngde"> @angularity/{core,config-files}</span></span></code></pre><ng-doc-blockquote type="warning" class="ngde"><p class="ngde">It is recommended to use async theming whenever possible, since the dependent <code class="ngde">material-design-color-utilities</code> package would bring 60KB of minified JavaScript to the bundle.</p></ng-doc-blockquote><h2 id="signature-symbols" href="packages/config-files" headinglink="true" class="ngde">Signature Symbols<ng-doc-heading-anchor class="ng-doc-anchor ngde" anchor="signature-symbols"></ng-doc-heading-anchor></h2><p class="ngde">The following symbols are the signature symbols of the <code class="ngde">@angularity/config-files</code> package. Click on the symbol to see the detailed documentation.</p><ng-doc-blockquote type="note" class="ngde"><p class="ngde">All Angularity symbols are well-documented with JSDoc.</p></ng-doc-blockquote><h3 id="exported-from-angularityconfig-files" href="packages/config-files" headinglink="true" class="ngde">Exported from <code class="ngde">@angularity/config-files</code><ng-doc-heading-anchor class="ng-doc-anchor ngde" anchor="exported-from-angularityconfig-files"></ng-doc-heading-anchor></h3><p class="ngde">Top-level:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/variables/config-files/defineConfigFile" class="ng-doc-code-anchor ngde">defineConfigFile</a></code><p class="ngde">Type-helper for creating <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/config-files/ConfigFileDefinition" class="ng-doc-code-anchor ngde">ConfigFileDefinition</a></code> objects.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/functions/config-files/useConfigFile" class="ng-doc-code-anchor ngde">useConfigFile</a></code><p class="ngde">Load the target config file and return a promise of its parsed content. The promise may be rejected if the loading fails.</p></li></ul><p class="ngde">Services:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/config-files/ConfigFileLoader" class="ng-doc-code-anchor ngde">ConfigFileLoader</a></code><p class="ngde">Service for loading configuration files.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/interfaces/config-files/ConfigFileParser" class="ng-doc-code-anchor ngde">ConfigFileParser</a></code><p class="ngde">Service for parsing the raw string content of a configuration file.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/interfaces/config-files/ConfigFileValidator" class="ng-doc-code-anchor ngde">ConfigFileValidator</a></code><p class="ngde">Service for validating the parsed content of a configuration file, making sure it conforms to the schema.</p></li></ul><p class="ngde">Implementations:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/config-files/TextParser" class="ng-doc-code-anchor ngde">TextParser</a></code><p class="ngde">Implementation of <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/config-files/ConfigFileParser" class="ng-doc-code-anchor ngde">ConfigFileParser</a></code> that simply wraps the raw string content.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/config-files/JsonParser" class="ng-doc-code-anchor ngde">JsonParser</a></code><p class="ngde">Implementation of <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/config-files/ConfigFileParser" class="ng-doc-code-anchor ngde">ConfigFileParser</a></code> that parses the string content as JSON, via the built-in <code class="ngde">JSON.parse</code> function.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/config-files/NoopValidator" class="ng-doc-code-anchor ngde">NoopValidator</a></code><p class="ngde">Implementation of <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/config-files/ConfigFileValidator" class="ng-doc-code-anchor ngde">ConfigFileValidator</a></code> that does nothing, i.e. the object is always considered valid.</p></li></ul><p class="ngde">Caching:</p><ul class="ngde"><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/classes/config-files/CacheConfigFiles" class="ng-doc-code-anchor ngde">CacheConfigFiles</a></code><p class="ngde">Decorator for <code class="ngde ng-doc-code-with-link"><a href="api/classes/config-files/ConfigFileLoader" class="ng-doc-code-anchor ngde">ConfigFileLoader</a></code> that caches the loaded configuration objects of each definition.</p><p class="ngde">One <code class="ngde ng-doc-code-with-link"><a href="api/interfaces/config-files/ConfigFileDefinition" class="ng-doc-code-anchor ngde">ConfigFileDefinition</a></code> object would cause only one load operation.</p></li><li class="ngde"><code class="ngde ng-doc-code-with-link"><a href="api/variables/config-files/httpServerCacheConfigFilesInterceptor" class="ng-doc-code-anchor ngde">httpServerCacheConfigFilesInterceptor</a></code><p class="ngde">HTTP interceptor that set a value to <code class="ngde ng-doc-code-with-link"><a href="api/variables/core-http/HTTP_SERVER_CACHE_KEY" class="ng-doc-code-anchor ngde">HTTP_SERVER_CACHE_KEY</a></code> if:</p><ul class="ngde"><li class="ngde">the <code class="ngde ng-doc-code-with-link"><a href="api/variables/config-files/CONFIG_FILE_REQUEST_CONTEXT" class="ng-doc-code-anchor ngde">CONFIG_FILE_REQUEST_CONTEXT</a></code> is present, and</li><li class="ngde">the config definition has an ID.</li></ul><p class="ngde">The value of the cache key is determined solely by the ID from the config definition.</p></li></ul>',v=(()=>{let e=class e extends c{constructor(){super(),this.pageType="guide",this.pageContent=w,this.page=o,this.demoAssets=u}};e.\u0275fac=function(i){return new(i||e)},e.\u0275cmp=d({type:e,selectors:[["ng-doc-page-5zxnosqh"]],features:[g([{provide:c,useExisting:e},h,o.providers??[]]),l],decls:1,vars:0,template:function(i,T){i&1&&t(0,"ng-doc-page")},dependencies:[r],encapsulation:2,changeDetection:0});let n=e;return n})(),P=[a(s({},(0,m.isRoute)(o.route)?o.route:{}),{path:"",component:v,title:"Config Files"})],V=P;export{v as PageComponent,V as default};
